using System;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class RecruitmentTasksPage:UserControl{DataGridView grid;public RecruitmentTasksPage(){BackColor=Theme.Background;var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55};var add=Ui.Button(L.Fa?"کار جدید":"New task");var done=Ui.Button(L.Fa?"انجام شد":"Complete",false);var refresh=Ui.Button(L.T("refresh"),false);add.Click+=(s,e)=>Add();done.Click+=(s,e)=>Complete();refresh.Click+=(s,e)=>LoadData();bar.Controls.Add(add);bar.Controls.Add(done);bar.Controls.Add(refresh);grid=Ui.Grid();Controls.Add(grid);Controls.Add(bar);grid.BringToFront();LoadData();}void LoadData(){grid.DataSource=Database.Query("SELECT t.Id,t.Title,c.FullName AS Candidate,t.Priority,t.DueAt,t.IsCompleted,t.CreatedAt FROM RecruitmentTasks t LEFT JOIN Candidates c ON c.Id=t.CandidateId WHERE t.AssignedTo=@u OR t.AssignedTo IS NULL ORDER BY t.IsCompleted,t.DueAt",new SqlParameter("@u",AppSession.UserId));}void Add(){using(var f=new Form{Text=L.Fa?"کار جذب جدید":"New recruitment task",Size=new Size(460,390),StartPosition=FormStartPosition.CenterParent}){var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(20)};var title=Ui.Text();title.Width=380;var cid=Ui.Text();cid.Width=380;var priority=new ComboBox{Width=380,DropDownStyle=ComboBoxStyle.DropDownList};priority.Items.AddRange(new object[]{"High","Medium","Low"});priority.SelectedIndex=1;var due=new DateTimePicker{Width=380,Value=DateTime.Today.AddDays(1)};var b=Ui.Button(L.T("save"));b.Click+=(s,e)=>{int id=0;int.TryParse(cid.Text,out id);if(string.IsNullOrWhiteSpace(title.Text)){MessageBox.Show(L.Fa?"عنوان را وارد کنید":"Enter a title");return;}Database.Exec("INSERT RecruitmentTasks(Title,CandidateId,AssignedTo,Priority,DueAt) VALUES(@t,@c,@u,@p,@d)",new SqlParameter("@t",title.Text.Trim()),new SqlParameter("@c",id==0?(object)DBNull.Value:id),new SqlParameter("@u",AppSession.UserId),new SqlParameter("@p",priority.Text),new SqlParameter("@d",due.Value));Database.Audit("Create","RecruitmentTask",title.Text);f.DialogResult=DialogResult.OK;f.Close();};p.Controls.Add(Ui.Label(L.Fa?"عنوان":"Title"));p.Controls.Add(title);p.Controls.Add(Ui.Label(L.Fa?"شناسه کارجو (اختیاری)":"Candidate ID (optional)"));p.Controls.Add(cid);p.Controls.Add(Ui.Label(L.Fa?"اولویت":"Priority"));p.Controls.Add(priority);p.Controls.Add(Ui.Label(L.Fa?"مهلت":"Due date"));p.Controls.Add(due);p.Controls.Add(b);f.Controls.Add(p);Theme.Apply(f);if(f.ShowDialog()==DialogResult.OK)LoadData();}}void Complete(){if(grid.CurrentRow==null)return;int id=Convert.ToInt32(grid.CurrentRow.Cells["Id"].Value);Database.Exec("UPDATE RecruitmentTasks SET IsCompleted=1,CompletedAt=SYSDATETIME() WHERE Id=@i",new SqlParameter("@i",id));Database.Audit("Complete","RecruitmentTask",id.ToString());LoadData();}}}